/bin/zsh -lc "apply_patch <<'PATCH'
*** Begin Patch
*** Update File: TopModule.sv
@@
 always @(pstate or data)
 begin
     case(pstate)
@@
         sf5:
             nstate=sf6;
         sf6:
-			nstate=s1;
+			nstate=data?sf1:s1;
         default:
             nstate=idle;
         endcase
 end

-always @(pstate or data or rst_n)
+always @(*)
 begin
-    if("'!rst_n==1) 
+	if(!rst_n) 
 		begin
 			match=1'"'b0;
 			not_match = 1'b0;
 		end
*** End Patch
PATCH

cat > tb.sv <<'TB'
"'`timescale 1ns/1ps
module tb;
  reg clk = 0;
  reg rst_n = 0;
  reg data = 0;
  wire match;
  wire not_match;

  TopModule dut(.clk(clk), .rst_n(rst_n), .data(data), .match(match), .not_match(not_match));

  always #5 clk = ~clk;

  task send_bit(input reg bitval);
    begin
      data = bitval;
      #10;
      $display("t=%0t data=%0b match=%0b not_match=%0b pstate=%0d", $time, data, match, not_match, dut.pstate);
    end
  endtask

  initial begin
    $display("group1 should MATCH: 011100");
    #1; rst_n = 0; data = 0;
    #9; rst_n = 1;
    send_bit(0); send_bit(1); send_bit(1); send_bit(1); send_bit(0); send_bit(0);

    $display("group2 should NOT MATCH: 111111");
    send_bit(1); send_bit(1); send_bit(1); send_bit(1); send_bit(1); send_bit(1);

    $display("group3 should NOT MATCH: 111100 (catches previous bug)");
    send_bit(1); send_bit(1); send_bit(1); send_bit(1); send_bit(0); send_bit(0);

    $finish;
  end
endmodule
TB

iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

